      if (A <= 0.003) continue;
      const k = clamp01(inner * 1.2 + (1 - d / L) * 0.25);
      out[i * 4] = col[0] + (core[0] - col[0]) * k; out[i * 4 + 1] = col[1] + (core[1] - col[1]) * k; out[i * 4 + 2] = col[2] + (core[2] - col[2]) * k;
