      const A = clamp01((acc / wsum * 3.2 + src[i] * 0.3) * I * fade);
      if (A <= 0.003) continue;
      out[i * 4] = col[0]; out[i * 4 + 1] = col[1]; out[i * 4 + 2] = col[2]; out[i * 4 + 3] = A * 255;
